s=Path('work/references_cumulative.bib').read_text()
for key in ['brouwerleech','gelfandponomarev1974modular','macdonald1981affine']:
    m=re.search(r'@\w+\{'+re.escape(key)+r',',s)
    start=m.start(); p=s.index('{',start); depth=1; i=p+1
    while depth:
        if s[i]=='{':depth+=1
        elif s[i]=='}':depth-=1
        i+=1
    entry=s[start:i]
    if key=='brouwerleech':
        entry=re.sub(r'annote\s*=\s*\{.*\}\s*$', 'annote = {Cumulative key retained. This run reopened the full notes and read Theorems 1.1 and 1.2. Prior cumulative verification records the uniqueness proof reading. The PDF is undated; no crawl date is used as a publication date.}\n}',entry,flags=re.S)
    elif key=='gelfandponomarev1974modular':
        entry=re.sub(r'annote\s*=\s*\{.*\}\s*$', 'annote = {Cumulative key retained. This run reopened Math-Net metadata; previous cumulative verification records full-text reading. Here used only as a thematic lattice-representation comparison, not an exact identification of the incomplete notebook example.}\n}',entry,flags=re.S)
    elif key=='macdonald1981affine':
        entry=re.sub(r'annote\s*=\s*\{.*\}\s*$', 'annote = {Cumulative key retained. This run reopened Numdam metadata and confirmed expose 577, June 1981. Used to identify the explicit reading recommendation; no unrecorded theorem imported.}\n}',entry,flags=re.S)
    entries.append(entry+'\n')
text='\n'.join(entries).replace(r'\textquotesingle',"'")
(root/'references.bib').write_text(text)
print('Wrote',len(entries),'bibliographic entries')
